fn peak(a:[*]const i64,lo:isize,hi:isize,n:isize)i64{const mid=lo+@divTrunc(hi-lo,2);if((mid==0 or a[@intCast(mid-1)]<=a[@intCast(mid)]) and(mid==n-1 or a[@intCast(mid+1)]<=a[@intCast(mid)]))return mid;if(mid>0 and a[@intCast(mid-1)]>a[@intCast(mid)])return peak(a,lo,mid-1,n);return peak(a,mid+1,hi,n);}
export fn peak_element(v:[*c]const i64,n:usize)i64{if(v==null or n<2 or n>129 or v[0]<1 or v[0]>128 or n!=@as(usize,@intCast(v[0]))+1)return -1;const count:usize=@intCast(v[0]);for(0..count)|i|{if(v[i+1]<-2147483648 or v[i+1]>2147483647)return -1;}return peak(v+1,0,@intCast(count-1),@intCast(count));}
